**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    // up[i] = ile krokow rosnacych konczy sie na i
    vector<int> up(n, 0);
    for (int i = 1; i < n; i++)
        if (T[i] > T[i - 1]) up[i] = up[i - 1] + 1;

    // down[i] = ile krokow malejacych zaczyna sie na i
    vector<int> down(n, 0);
    for (int i = n - 2; i >= 0; i--)
        if (T[i] > T[i + 1]) down[i] = down[i + 1] + 1;

    int maxDl = 0, maxSzczyt = 0;
    for (int i = 1; i < n - 1; i++) {
        if (up[i] > 0 && down[i] > 0) {
            int dl = up[i] + down[i] + 1;
            if (dl > maxDl) {
                maxDl = dl;
                maxSzczyt = i;
            }
        }
    }

    int start = maxSzczyt - up[maxSzczyt];
    int koniec = maxSzczyt + down[maxSzczyt];

    cout << "a) Dlugosc gory: " << maxDl << endl;
    cout << "b) Poczatek: " << start + 1
         << ", szczyt: " << maxSzczyt + 1
         << ", koniec: " << koniec + 1 << endl;
    cout << "c) Wartosc szczytu: " << T[maxSzczyt] << endl;
    cout << "d) Elementy:";
    for (int i = start; i <= koniec; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Obliczamy dwie tablice pomocnicze: up[i] (ile kolejnych krokow rosnacych konczy sie na pozycji i) i down[i] (ile kolejnych krokow malejacych zaczyna sie na pozycji i). Gora o szczycie w i ma dlugosc up[i]+down[i]+1. Wymog: zarowno up[i]>0 jak i down[i]>0.

Weryfikacja (dane: 2,5,8,12,9,6,3,7,10,15,13,11,4,1):
up[]:  0,1,2,3,0,0,0,1,2,3,0,0,0,0
down[]:0,0,0,3,2,1,0,0,0,4,3,2,1,0

Szczyty (up>0 i down>0):
- i=3: up=3, down=3, dl=7. maxDl=7, maxSzczyt=3.
- i=9: up=3, down=4, dl=8. maxDl=8, maxSzczyt=9.

Najdluzsza gora: dl=8, szczyt=9 (poz.10).
start = 9-3 = 6 (poz.7). koniec = 9+4 = 13 (poz.14).
Elementy: T[6..13] = 3,7,10,15,13,11,4,1.
Szczyt: T[9]=15.
